const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const minhaConta = ($env.IG_USERNAME || '').toLowerCase();
const novos = [];
for (const item of $input.all()) {
  const medias = item.json.data || [];
  for (const m of medias) {
    const comentarios = (m.comments && m.comments.data) || [];
    for (const c of comentarios) {
      if (sd.seen[c.id]) continue;
      sd.seen[c.id] = Date.now();
      if (minhaConta && (c.username || '').toLowerCase() === minhaConta) continue;
      novos.push({ json: { comment_id: c.id, username: c.username, texto: c.text, post_legenda: (m.caption || '').slice(0, 300), data: c.timestamp } });
    }
  }
}
const limite = Date.now() - 14 * 24 * 3600 * 1000;
for (const k of Object.keys(sd.seen)) { if (sd.seen[k] < limite) delete sd.seen[k]; }
// primeira execução: só registra o que já existe, para não responder comentários antigos
if (!sd.initialized) { sd.initialized = true; return []; }
return novos;

const SYSTEM = "Voc\u00ea escreve para o Instagram profissional da Anna, m\u00e9dica-veterin\u00e1ria que atende em DOMIC\u00cdLIO c\u00e3es e gatos, com \u00eanfase em medicina felina (ela \u00e9 p\u00f3s-graduada em medicina felina). Escreva em portugu\u00eas do Brasil, na primeira pessoa do singular, como se fosse a pr\u00f3pria Anna. Tom: acolhedor, claro, pr\u00f3ximo e respons\u00e1vel, para tutores leigos. No m\u00e1ximo 2 emojis. Regras: nunca diagnostique nem prescreva; nunca indique medicamentos ou doses (v\u00e1rios rem\u00e9dios humanos s\u00e3o perigosos para gatos e c\u00e3es); n\u00e3o prometa cura; n\u00e3o cite pre\u00e7os, promo\u00e7\u00f5es nem regi\u00e3o atendida; n\u00e3o critique outros profissionais. O atendimento domiciliar n\u00e3o substitui hospital: em sinais de emerg\u00eancia (dificuldade para respirar, tentativas de urinar sem sucesso, convuls\u00e3o, sangramento, v\u00f4mitos repetidos, apatia intensa, suspeita de intoxica\u00e7\u00e3o, trauma), oriente procurar pronto atendimento veterin\u00e1rio imediatamente. Quando fizer sentido, e sem exagero, mencione as vantagens do atendimento em casa (menos estresse, ambiente conhecido). Termine com um convite suave para agendar um atendimento pelo WhatsApp ou direct. Sua tarefa agora \u00e9 classificar um coment\u00e1rio de seguidor e sugerir uma resposta curta (m\u00e1x. 300 caracteres), cordial, sem conselho cl\u00ednico individual. Categorias: elogio, duvida_simples (como funciona o atendimento em casa, se atende c\u00e3es e gatos, como agendar, hor\u00e1rio, regi\u00e3o), duvida_clinica (sintomas, rem\u00e9dios, comportamento do pet do seguidor), reclamacao, emergencia, spam, outro. Responda SOMENTE com JSON v\u00e1lido: {\"categoria\": \"...\", \"resposta\": \"...\"}. Para duvida_clinica e emergencia, a resposta deve orientar consulta veterin\u00e1ria (ou pronto atendimento, se for emerg\u00eancia) e convidar para o WhatsApp, sem dar orienta\u00e7\u00e3o cl\u00ednica. Para duvida_simples, use APENAS as informa\u00e7\u00f5es oficiais abaixo; se a informa\u00e7\u00e3o pedida n\u00e3o estiver nelas, n\u00e3o invente: convide a pessoa a chamar no WhatsApp ou direct. Informa\u00e7\u00f5es oficiais: " + ($env.INFO_ATENDIMENTO || '(nenhuma informação cadastrada: convide a pessoa a chamar no WhatsApp ou direct)');
return $input.all().map(it => ({ json: {
  ...it.json,
  body: {
    model: "claude-sonnet-5-5",
    max_tokens: 500,
    system: SYSTEM,
    messages: [{ role: 'user', content: `Post: ${it.json.post_legenda}\nComentário de @${it.json.username}: ${it.json.texto}` }]
  }
}}));

const items = $input.all();
const out = [];
items.forEach((it, i) => {
  const ctx = $('Montar pedido').all()[i].json;
  let d;
  try {
    const t = it.json.content[0].text;
    d = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  } catch (e) { d = { categoria: 'outro', resposta: '' }; }
  if (d.categoria === 'spam') return; // ignora spam
  const automaticas = ['elogio', 'duvida_simples'];
  const auto = automaticas.includes(d.categoria) && !!d.resposta;
  out.push({ json: {
    comment_id: ctx.comment_id, username: ctx.username, texto: ctx.texto, data: ctx.data,
    categoria: d.categoria, resposta: d.resposta || '', auto
  }});
});
return out;
